package org.icu.sepsis.sepsis;
import static org.junit.jupiter.api.Assertions.*;
import java.time.*;import java.util.*;import org.junit.jupiter.api.Test;import org.icu.sepsis.domain.Domain.*;
class MewsScreeningTest {
 final Instant now=Instant.parse("2026-11-07T02:00:00Z");final MewsProperties config=new MewsProperties();
 Patient patient(){Patient p=new Patient();p.id="synthetic";p.encounterId="stay";p.department="ICU";p.admittedAt=now.minusSeconds(86400);p.birthDate=LocalDate.of(1980,1,1);return p;}
 Observation o(String code,double value,int age){var o=new Observation();o.patientId="synthetic";o.encounterId="stay";o.department="ICU";o.parameterCode=code;o.value=value;o.unit=code.startsWith("SBP")?"mmHg":code.equals("HR")?"bpm":code.equals("RR")?"/min":code.equals("TEMP")?"°C":"AVPU";o.sourceSystem="SmartCare.bedside";o.sourceRecordId=code+age;o.eventTime=now.minusSeconds(age);o.qualityStatus="valid";o.ingestTimeBasis="unknown";return o;}
 List<Observation> complete(){var r=new ArrayList<>(List.of(o("SBP_NIBP",95,60),o("HR",115,60),o("RR",22,60),o("TEMP",37,60),o("AVPU",0,60)));r.get(4).value=null;r.get(4).text="清醒";return r;}
 Map<String,Object> run(List<Observation> rows){return MewsScreening.evaluate(patient(),rows,now,config);}
 @SuppressWarnings("unchecked") Map<String,Object> channel(Map<String,Object> result){return ((List<Map<String,Object>>)result.get("channels")).get(0);}
 @Test void recomputesFivePointsOnlyFromBedsideAndPreservesSources(){var rows=complete();var recorded=o("MEWS",14,0);recorded.sourceSystem="SmartCare.score";rows.add(recorded);var result=run(rows);assertEquals(5,channel(result).get("total"));assertEquals(true,result.get("triggered"));assertEquals(60L,Duration.between((Instant)channel(result).get("oldestAt"),now).getSeconds());assertEquals(5,((List<?>)channel(result).get("components")).size());Collections.reverse(rows);assertEquals(channel(result).get("total"),channel(run(rows)).get("total"));}
 @Test void scoreBoundariesAreExplicitAndValuesNeverRounded(){double[][] sbp={{70,3},{71,2},{80,2},{81,1},{100,1},{101,0},{199,0},{200,2}};for(var a:sbp)assertEquals((int)a[1],MewsScreening.points("SBP",a[0]));double[][] hr={{40,2},{41,1},{50,1},{51,0},{100,0},{101,1},{110,1},{111,2},{129,2},{130,3}};for(var a:hr)assertEquals((int)a[1],MewsScreening.points("HR",a[0]));double[][] rr={{8,2},{9,0},{14,0},{15,1},{20,1},{21,2},{29,2},{30,3}};for(var a:rr)assertEquals((int)a[1],MewsScreening.points("RR",a[0]));assertEquals(2,MewsScreening.points("TEMP",35d));assertEquals(0,MewsScreening.points("TEMP",35.01));assertEquals(0,MewsScreening.points("TEMP",38.499));assertEquals(2,MewsScreening.points("TEMP",38.5));assertNull(MewsScreening.points("HR",100.9));assertNull(MewsScreening.points("HR",Double.NaN));}
 @Test void sedationAndGcsDoNotBecomeAvpuOrZero(){var r=complete();r.get(4).text="镇静";r.add(o("GCS",15,60));assertNull(channel(run(r)).get("total"));assertNull(run(r).get("triggered"));assertEquals(5,channel(run(r)).get("partialScore"));assertNull(MewsScreening.avpu("浅昏迷"));assertEquals(1,MewsScreening.avpu("V"));assertEquals(2,MewsScreening.avpu("对疼痛有反应"));assertEquals(3,MewsScreening.avpu("无反应"));}
 @Test void exactFreshnessBoundaryAndSkewAreInclusiveButOlderOrWiderIsUnknown(){var r=complete();r.forEach(o->o.eventTime=now.minusSeconds(1800));assertEquals(5,channel(run(r)).get("total"));r.get(0).eventTime=now.minusSeconds(1801);assertNull(channel(run(r)).get("total"));r=complete();r.get(0).eventTime=now.minusSeconds(960);assertEquals(900L,channel(run(r)).get("spanSeconds"));assertEquals(5,channel(run(r)).get("total"));r.get(0).eventTime=now.minusSeconds(961);assertNull(channel(run(r)).get("total"));}
 @Test void futureResultsAdmissionAndEncounterDoNotEnterScore(){for(String problem:List.of("future","ingestion","admission","encounter","department")){var r=complete();var o=r.get(0);switch(problem){case "future":o.eventTime=now.plusSeconds(1);break;case "ingestion":o.ingestTime=now.plusSeconds(1);break;case "admission":o.eventTime=now.minusSeconds(86401);break;case "encounter":o.encounterId="other";break;default:o.department="other";}assertNull(channel(run(r)).get("total"),problem);}}
 @Test void newestConflictOrInvalidValueCannotFallBackToOlderCompleteScore(){for(boolean conflict:List.of(true,false)){var r=complete();var n=o("HR",130,10);r.add(n);if(conflict)r.add(o("HR",80,10));else n.qualityStatus="invalid";assertNull(channel(run(r)).get("total"));}}
 @Test void bloodPressureChannelsStaySeparateAndGenericCannotHideThem(){var r=complete();r.add(o("SBP_IBP",65,60));r.add(o("SBP",120,60));var result=run(r);var cs=(List<?>)result.get("channels");assertEquals(2,cs.size());assertEquals(true,result.get("triggered"));assertEquals("SBP_IBP",channel(result).get("channel"));assertEquals(7,channel(result).get("total"));}
 @Test void populationAndDisabledStatesCannotProduceAdultAlert(){var p=patient();p.birthDate=null;assertNull(MewsScreening.evaluate(p,complete(),now,config).get("triggered"));p.birthDate=LocalDate.of(2020,1,1);assertEquals("not_adult",MewsScreening.evaluate(p,complete(),now,config).get("population"));config.setEnabled(false);assertNull(run(complete()).get("triggered"));}
 @Test void invalidUnitsAndSourceScoresCannotFillMissingComponents(){var r=complete();r.get(1).unit="other";assertNull(channel(run(r)).get("total"));r=complete();r.get(1).sourceSystem="SmartCare.score";assertNull(channel(run(r)).get("total"));assertThrows(IllegalArgumentException.class,()->config.setReviewThreshold(15));}
 @Test void fourHourlyTemperatureIsCarriedWithActualTimeButExpiresAfterFourHours(){var r=complete();r.get(3).eventTime=now.minusSeconds(14400);var c=channel(run(r));assertEquals(5,c.get("total"));assertEquals(0L,c.get("coreSpanSeconds"));assertEquals(14340L,c.get("spanSeconds"));var parts=(List<?>)c.get("components");assertEquals(true,((Map<?,?>)parts.get(3)).get("carriedForward"));assertEquals(14400L,((Map<?,?>)parts.get(3)).get("ageSeconds"));r.get(3).eventTime=now.minusSeconds(14401);c=channel(run(r));assertNull(c.get("total"));assertEquals(false,((Map<?,?>)((List<?>)c.get("components")).get(3)).get("carriedForward"));}
 @Test void futureTemperatureAndNewInvalidTemperatureNeverReplaceValidTimingRules(){var r=complete();r.get(3).eventTime=now.plusSeconds(1);assertNull(channel(run(r)).get("total"));r=complete();var invalid=o("TEMP",39,0);invalid.value=null;invalid.qualityStatus="invalid";r.add(invalid);assertNull(channel(run(r)).get("total"));}
}
